"""Reproduce information-bottleneck teaching SVGs; milestones from v3 §3.6."""
from pathlib import Path
from html import escape
out=Path(__file__).resolve().parents[1]/'public/figures/information-bottleneck'
out.mkdir(parents=True,exist_ok=True)
def text(x,y,s,size=19):
    return f'<text x="{x}" y="{y}" font-size="{size}">{escape(s)}</text>'
def box(x,y,w,a,b,color='#ddd9fa'):
    return f'<rect x="{x}" y="{y}" width="{w}" height="86" rx="12" fill="{color}" stroke="#71849a"/>'+text(x+14,y+32,a)+text(x+14,y+62,b,16)
def arrow(x,y,a,b):
    return f'<path d="M{x} {y} L{a} {b}" stroke="#53677d" stroke-width="3" fill="none" marker-end="url(#a)"/>'
def svg(name,title,desc,body,h=440):
    (out/f'{name}.svg').write_text(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 940 {h}" role="img" aria-labelledby="t d"><title id="t">{escape(title)}</title><desc id="d">{escape(desc)}</desc><defs><marker id="a" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8" fill="#53677d"/></marker></defs><rect width="940" height="{h}" rx="18" fill="#f3f6fb"/><g font-family="Arial,sans-serif" fill="#17304b">'+text(28,43,title,25)+body+'</g></svg>')
svg('problem','01 / Preserve the relevant bit','Toy grouping of four equally likely inputs by A; B is independent nuisance.',box(30,95,230,'X = (A, B)','00 or 01: label 0','#d4eee7')+box(30,260,230,'X = (A, B)','10 or 11: label 1','#d4eee7')+arrow(270,138,340,138)+arrow(270,303,340,303)+box(350,95,240,'T = A = 0','Forget which B occurred')+box(350,260,240,'T = A = 1','Forget which B occurred')+arrow(600,138,660,138)+arrow(600,303,660,303)+box(670,95,235,'Predict Y = 0','Exactly correct','#ffe6cb')+box(670,260,235,'Predict Y = 1','Exactly correct','#ffe6cb')+text(30,405,'Toy: 2 input bits → 1 representation bit → all 1 label bit retained.',18))
svg('architecture','02 / Prediction and measurement are different paths','Learned classifier trained by cross-entropy; frozen checkpoints analyzed by quantization.',box(30,95,230,'A · Batch of inputs','m × 12 binary values','#d4eee7')+arrow(270,138,335,138)+box(345,95,250,'B · Dense layers','Tᵢ: m × dᵢ; learned Wᵢ, bᵢ')+arrow(605,138,660,138)+box(670,95,240,'C · Sigmoid output','Predicted label probability')+box(670,250,240,'D · Cross-entropy','Label → loss → SGD','#ffe6cb')+arrow(790,190,790,240)+text(30,232,'Training: SGD updates weights.',18)+box(30,340,360,'E · Freeze checkpoint; enumerate X','Bin each activation; one tuple per layer','#d4eee7')+arrow(470,185,470,290)+arrow(470,290,210,290)+arrow(210,290,210,330)+arrow(400,383,540,383)+box(550,340,360,'F · Joint distributions → information','Plot I(X; T) and I(T; Y); compare with IB','#ffe6cb')+text(30,477,'Inference: fixed A → B → C. No labels, binning, IB solver or optimizer.',19)+text(30,519,'Green: input / measurement   Purple: predictor   Orange: loss / analysis',18),550)
body=arrow(95,365,850,365)+arrow(95,365,95,85)+text(560,410,'I(X; T): retained input bits →',19)+text(112,92,'I(T; Y): label bits ↑',19)
for x,label in [(95,'0'),(440,'1'),(785,'2')]: body+=text(x-4,391,label,16)
body+=text(64,160,'1',16)+text(64,370,'0',16)
for x,y,label,dx,dy in [(785,155,'T = X: (2, 1)',-130,-20),(440,155,'T = A: (1, 1)',-70,-20),(440,365,'T = B: (1, 0)',-70,-20),(95,365,'Constant',15,-20)]:
 body+=f'<circle cx="{x}" cy="{y}" r="7" fill="#168373"/>'+text(x+dx,y+dy,label,17)
body+='<path d="M740 315 C755 265 775 205 710 187 C640 171 550 177 485 182" stroke="#8463b5" stroke-width="5" fill="none" marker-end="url(#a)"/>'+text(770,265,'Fit ↑',18)+text(500,225,'Then compress ←',18)+text(120,300,'Illustrative trajectory; not measured data.',17)
svg('plane','03 / Two coordinates, two questions','Toy information plane; rising then leftward trajectory is schematic.',body)
svg('binning','04 / Exact values can differ while bins merge','Four-bin toy illustration, not the paper’s 30-bin experiment.',text(30,92,'Four equally likely inputs, with labels 0, 0, 1, 1',19)+box(30,125,370,'Earlier exact activations','−0.75, −0.25, 0.25, 0.75','#d4eee7')+arrow(410,168,500,168)+box(510,125,395,'Four occupied bins','Each has probability ¼; entropy = 2 bits')+box(30,255,370,'Later exact activations','−0.90, −0.80, 0.80, 0.90','#d4eee7')+arrow(410,298,500,298)+box(510,255,395,'Two occupied bins','Each has probability ½; entropy = 1 bit')+text(30,385,'Toy bin edges: −1, −0.5, 0, 0.5, 1. Label information stays 1 bit.',18)+text(30,418,'All four exact values stay distinct: exact input information stays 2 bits.',18))
svg('bottleneck','05 / Assign inputs by label-distribution similarity','IB consistency loop and one provisional numerical assignment.',box(30,90,260,'Known input rule','p(Y = 1 | x) = 0.9','#d4eee7')+arrow(300,133,350,133)+box(360,90,260,'Two candidate decoders','Group probabilities: 0.9, 0.1')+arrow(630,133,670,133)+box(680,90,230,'KL mismatch','0 or 1.758 nats','#ffe6cb')+box(30,275,260,'Update encoder','Assignments: 0.853, 0.147')+box(360,275,260,'Update group masses','p(t) = sum over inputs','#d4eee7')+box(680,275,230,'Update decoders','Mix labels within group','#d4eee7')+arrow(790,185,790,230)+arrow(790,230,160,230)+arrow(160,230,160,265)+arrow(300,318,350,318)+arrow(630,318,670,318)+text(30,408,'Repeat with updated distributions. Toy: equal initial group masses, β = 1.',18)+text(30,446,'This is theoretical IB iteration; classifier training uses cross-entropy.',18),480)
svg('dynamics','06 / Carry weights forward; measure at checkpoints','Directed early updates versus fluctuation-dominated late updates.',box(30,90,265,'Current weights θₖ','Draw a training minibatch')+arrow(305,133,345,133)+box(355,90,265,'Gradient g = μ + ξ','Mean plus batch fluctuation','#ffe6cb')+arrow(630,133,670,133)+box(680,90,230,'Next weights θₖ₊₁','θₖ − ηg; repeat')+text(30,230,'Early: drift dominates',21)+text(490,230,'Late: fluctuations dominate',21)+arrow(40,290,125,290)+arrow(135,290,220,290)+arrow(230,290,315,290)+arrow(505,290,570,265)+arrow(570,265,550,315)+arrow(550,315,625,295)+arrow(625,295,600,335)+text(30,370,'Toy step: mean 0.01; STD 0.001',18)+text(490,370,'Toy step: mean 0.0001; STD 0.002',18)+text(30,417,'Noise-dominated does not mean frozen weights or guaranteed useful compression.',18))
svg('evidence','07 / Reported depth milestones, not a speedup ratio','Source v3 section 3.6, Figure 5: one versus six hidden layers.',text(30,92,'Synthetic 4096-pattern task · 80% training coverage · 50 randomized runs',18)+box(30,135,420,'1 hidden layer · after 10,000 epochs','Did not achieve “good” label information','#ddd9fa')+box(490,135,420,'6 hidden layers · within 400 epochs','Reached full relevant output information','#d4eee7')+text(30,279,'Metric: output label information I(Y; output), not percent accuracy.',19)+text(30,321,'Paper reports qualitative attainment descriptions, not a common threshold.',18)+text(30,363,'Architectures differ. No wall-clock times or matched-compute ratio supplied.',18)+text(30,411,'Source: course PDF §3.6 / Figure 5. Milestone cards reproduce prose values.',17))
